import { ArrowDownRight, ArrowUpRight, DollarSign, Eye, Users } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import type { DemoMeta } from "@/registry";

export const meta: DemoMeta = {
  name: "アナリティクス概要",
  category: "ダッシュボード",
  description: "3つのKPIタイルとグラデーション付きエリアチャートを備えた概要パネル。",
  align: "full",
  isNew: true,
  tags: ["analytics", "charts", "kpi"],
};

const KPIS = [
  {
    label: { ja: "総収益", en: "Total revenue" },
    value: "¥4,820,400",
    delta: 12.4,
    icon: DollarSign,
    up: true,
  },
  {
    label: { ja: "アクティブユーザー", en: "Active users" },
    value: "38,294",
    delta: 8.1,
    icon: Users,
    up: true,
  },
  {
    label: { ja: "ページビュー", en: "Page views" },
    value: "1.24M",
    delta: -2.6,
    icon: Eye,
    up: false,
  },
];

// 28日分のサンプルデータ（0-100）
const SERIES = [
  32, 38, 30, 44, 41, 52, 48, 60, 55, 67, 62, 71, 69, 78, 74, 82, 79, 88, 84,
  92, 86, 95, 90, 98, 93, 100, 96, 99,
];

function buildPaths(data: number[], width: number, height: number, pad: number) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const span = max - min || 1;
  const innerW = width - pad * 2;
  const innerH = height - pad * 2;
  const points = data.map((v, i) => {
    const x = pad + (i / (data.length - 1)) * innerW;
    const y = pad + innerH - ((v - min) / span) * innerH;
    return [x, y] as const;
  });
  const line = points
    .map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`)
    .join(" ");
  const area = `${line} L${(width - pad).toFixed(2)},${(height - pad).toFixed(
    2
  )} L${pad.toFixed(2)},${(height - pad).toFixed(2)} Z`;
  return { line, area, points };
}

export default function AnalyticsOverview() {
  const en =
    typeof document !== "undefined" &&
    document.documentElement.lang === "en";
  const W = 760;
  const H = 240;
  const PAD = 12;
  const { line, area, points } = buildPaths(SERIES, W, H, PAD);
  const last = points[points.length - 1];

  return (
    <Card className="w-full">
      <CardContent className="p-6">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <div>
            <h3 className="text-base font-semibold tracking-tight">
              {en ? "Performance overview" : "パフォーマンス概要"}
            </h3>
            <p className="text-sm text-muted-foreground">
              {en ? "Last 28 days" : "過去28日間の推移"}
            </p>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <span className="flex items-center gap-1.5">
              <span className="size-2 rounded-full bg-primary" />
              {en ? "Revenue" : "収益"}
            </span>
            <span className="flex items-center gap-1.5">
              <span className="size-2 rounded-full bg-muted-foreground/40" />
              {en ? "Previous period" : "前期間"}
            </span>
          </div>
        </div>

        <div className="mt-5 grid gap-3 sm:grid-cols-3">
          {KPIS.map((kpi) => (
            <div
              key={kpi.label.en}
              className="rounded-lg border bg-muted/30 p-4"
            >
              <div className="flex items-center justify-between">
                <span className="text-xs font-medium text-muted-foreground">
                  {en ? kpi.label.en : kpi.label.ja}
                </span>
                <kpi.icon className="size-4 text-muted-foreground" />
              </div>
              <div className="mt-2 text-2xl font-bold tabular-nums tracking-tight">
                {kpi.value}
              </div>
              <div
                className={cn(
                  "mt-1 flex items-center gap-1 text-xs font-medium tabular-nums",
                  kpi.up ? "text-emerald-500" : "text-rose-500"
                )}
              >
                {kpi.up ? (
                  <ArrowUpRight className="size-3.5" />
                ) : (
                  <ArrowDownRight className="size-3.5" />
                )}
                {kpi.up ? "+" : ""}
                {kpi.delta}%
                <span className="text-muted-foreground">
                  {en ? "vs last month" : "先月比"}
                </span>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-6 w-full overflow-hidden rounded-lg border bg-muted/20 p-2">
          <svg
            viewBox={`0 0 ${W} ${H}`}
            className="h-56 w-full"
            preserveAspectRatio="none"
            role="img"
            aria-label={en ? "Revenue trend chart" : "収益推移チャート"}
          >
            <defs>
              <linearGradient id="ao-fill" x1="0" y1="0" x2="0" y2="1">
                <stop
                  offset="0%"
                  stopColor="hsl(var(--primary))"
                  stopOpacity="0.35"
                />
                <stop
                  offset="100%"
                  stopColor="hsl(var(--primary))"
                  stopOpacity="0"
                />
              </linearGradient>
            </defs>
            {[0.25, 0.5, 0.75].map((g) => (
              <line
                key={g}
                x1={PAD}
                x2={W - PAD}
                y1={PAD + (H - PAD * 2) * g}
                y2={PAD + (H - PAD * 2) * g}
                className="stroke-border"
                strokeWidth={1}
                strokeDasharray="3 5"
              />
            ))}
            <path d={area} fill="url(#ao-fill)" />
            <path
              d={line}
              fill="none"
              stroke="hsl(var(--primary))"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              vectorEffect="non-scaling-stroke"
            />
            <circle
              cx={last[0]}
              cy={last[1]}
              r={4}
              fill="hsl(var(--primary))"
              stroke="hsl(var(--background))"
              strokeWidth={2}
            />
          </svg>
        </div>
      </CardContent>
    </Card>
  );
}

import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import type { DemoMeta } from "@/registry";

export const meta: DemoMeta = {
  name: "コントリビューションヒートマップ",
  category: "ダッシュボード",
  description: "週×曜日のGitHub風コントリビューショングリッド。強度バケットと凡例付き。",
  align: "full",
  isNew: true,
  tags: ["analytics", "heatmap", "activity"],
};

const WEEKS = 26;
const DAYS = 7;
const DAY_LABELS_JA = ["月", "", "水", "", "金", "", "日"];
const DAY_LABELS_EN = ["Mon", "", "Wed", "", "Fri", "", "Sun"];

// 決定的な擬似乱数で強度バケット(0-4)を生成
function bucket(week: number, day: number): number {
  const seed = (week * 7 + day) * 9301 + 49297;
  const r = (seed % 233280) / 233280;
  const weekend = day >= 5 ? 0.5 : 1;
  const v = r * weekend;
  if (v < 0.45) return 0;
  if (v < 0.62) return 1;
  if (v < 0.78) return 2;
  if (v < 0.9) return 3;
  return 4;
}

const LEVELS = [
  "bg-muted",
  "bg-emerald-500/25",
  "bg-emerald-500/50",
  "bg-emerald-500/75",
  "bg-emerald-500",
];

const MONTH_LABELS_JA = ["1月", "", "2月", "", "3月", "", "4月", "", "5月", "", "6月", "", "7月"];
const MONTH_LABELS_EN = ["Jan", "", "Feb", "", "Mar", "", "Apr", "", "May", "", "Jun", "", "Jul"];

export default function ContributionHeatmap() {
  const en =
    typeof document !== "undefined" &&
    document.documentElement.lang === "en";
  const dayLabels = en ? DAY_LABELS_EN : DAY_LABELS_JA;
  const monthLabels = en ? MONTH_LABELS_EN : MONTH_LABELS_JA;
  const grid = Array.from({ length: WEEKS }, (_, w) =>
    Array.from({ length: DAYS }, (_, d) => bucket(w, d))
  );
  const total = grid.flat().reduce((a, b) => a + b * 3, 0);

  return (
    <Card className="w-full">
      <CardContent className="p-6">
        <div className="mb-4 flex flex-wrap items-end justify-between gap-2">
          <div>
            <h3 className="text-base font-semibold tracking-tight">
              {en ? "Activity" : "アクティビティ"}
            </h3>
            <p className="text-sm text-muted-foreground tabular-nums">
              {en ? (
                <>
                  {total.toLocaleString("en-US")} contributions in the last 6
                  months
                </>
              ) : (
                <>過去6ヶ月で {total.toLocaleString("ja-JP")} 件のコントリビューション</>
              )}
            </p>
          </div>
        </div>

        <div className="w-full overflow-x-auto">
          <div className="inline-flex gap-1.5">
            <div className="flex flex-col gap-[3px] pr-1 pt-5 text-[10px] text-muted-foreground">
              {dayLabels.map((l, i) => (
                <span key={i} className="flex h-3 items-center">
                  {l}
                </span>
              ))}
            </div>

            <div>
              <div className="mb-1 flex text-[10px] text-muted-foreground">
                {grid.map((_, w) => (
                  <span key={w} className="w-3" style={{ marginRight: 3 }}>
                    {w < monthLabels.length ? monthLabels[w] : ""}
                  </span>
                ))}
              </div>
              <div className="flex gap-[3px]">
                {grid.map((week, w) => (
                  <div key={w} className="flex flex-col gap-[3px]">
                    {week.map((lvl, d) => (
                      <div
                        key={d}
                        className={cn("size-3 rounded-[3px]", LEVELS[lvl])}
                        title={
                          en
                            ? `Week ${w + 1} ${dayLabels[d] || ""}: level ${lvl}`
                            : `第${w + 1}週 ${dayLabels[d] || ""}: 強度${lvl}`
                        }
                      />
                    ))}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="mt-4 flex items-center justify-end gap-1.5 text-[11px] text-muted-foreground">
          <span>{en ? "Less" : "少"}</span>
          {LEVELS.map((c, i) => (
            <span key={i} className={cn("size-3 rounded-[3px]", c)} />
          ))}
          <span>{en ? "More" : "多"}</span>
        </div>
      </CardContent>
    </Card>
  );
}

import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import type { DemoMeta } from "@/registry";

export const meta: DemoMeta = {
  name: "コンバージョンファネル",
  category: "ダッシュボード",
  description: "各ステージの割合と離脱率を表示する降順のコンバージョンファネル。",
  align: "full",
  isNew: true,
  tags: ["analytics", "funnel", "conversion"],
};

const STAGES = [
  { label: "訪問", labelEn: "Visits", value: 48200 },
  { label: "サインアップ", labelEn: "Sign-ups", value: 21400 },
  { label: "トライアル開始", labelEn: "Trial started", value: 12850 },
  { label: "アクティブ化", labelEn: "Activated", value: 7320 },
  { label: "有料転換", labelEn: "Converted", value: 3180 },
];

const ACCENTS = [
  "bg-sky-500",
  "bg-indigo-500",
  "bg-violet-500",
  "bg-fuchsia-500",
  "bg-rose-500",
];

export default function FunnelChart() {
  const en =
    typeof document !== "undefined" &&
    document.documentElement.lang === "en";
  const top = STAGES[0].value;

  return (
    <Card className="w-full">
      <CardContent className="p-6">
        <div className="flex items-end justify-between">
          <div>
            <h3 className="text-base font-semibold tracking-tight">
              {en ? "Conversion funnel" : "コンバージョンファネル"}
            </h3>
            <p className="text-sm text-muted-foreground">
              {en ? "Overall conversion " : "全体転換率"}{" "}
              <span className="font-medium text-foreground tabular-nums">
                {((STAGES[STAGES.length - 1].value / top) * 100).toFixed(1)}%
              </span>
            </p>
          </div>
        </div>

        <div className="mt-5 space-y-2.5">
          {STAGES.map((stage, i) => {
            const pct = (stage.value / top) * 100;
            const prev = i === 0 ? stage.value : STAGES[i - 1].value;
            const dropoff = i === 0 ? 0 : ((prev - stage.value) / prev) * 100;
            return (
              <div key={stage.label}>
                <div className="mb-1 flex items-center justify-between text-sm">
                  <span className="font-medium">
                    {en ? stage.labelEn : stage.label}
                  </span>
                  <span className="flex items-center gap-3">
                    <span className="tabular-nums text-muted-foreground">
                      {stage.value.toLocaleString(en ? "en-US" : "ja-JP")}
                    </span>
                    <span className="w-12 text-right font-semibold tabular-nums">
                      {pct.toFixed(1)}%
                    </span>
                  </span>
                </div>
                <div className="relative h-9 overflow-hidden rounded-md bg-muted/40">
                  <div
                    className={cn(
                      "flex h-full items-center rounded-md transition-all",
                      ACCENTS[i]
                    )}
                    style={{ width: `${Math.max(pct, 6)}%` }}
                  />
                  {i > 0 && (
                    <span className="absolute inset-y-0 right-2.5 flex items-center text-xs font-medium tabular-nums text-rose-500">
                      −{dropoff.toFixed(1)}% {en ? "drop-off" : "離脱"}
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </CardContent>
    </Card>
  );
}

import { Crown, Minus, TrendingDown, TrendingUp } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import type { DemoMeta } from "@/registry";

export const meta: DemoMeta = {
  name: "リーダーボード",
  category: "ダッシュボード",
  description: "順位・アバター・スコア・変動を表示し、上位3名を強調するランキング。",
  align: "center",
  isNew: true,
  tags: ["analytics", "leaderboard", "ranking"],
};

type Entry = {
  name: string;
  score: number;
  move: number; // 順位の変動 (+上昇 / -下降 / 0)
};

const ENTRIES: Entry[] = [
  { name: "佐藤 美咲", score: 9824, move: 0 },
  { name: "Liam Carter", score: 9410, move: 2 },
  { name: "田中 翔太", score: 9187, move: -1 },
  { name: "Aisha Khan", score: 8640, move: 1 },
  { name: "鈴木 健", score: 8021, move: -2 },
  { name: "Noah Kim", score: 7755, move: 0 },
];

function initials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 2);
  return parts[0][0] + parts[1][0];
}

const TOP_RING = [
  "ring-amber-400/70 text-amber-500",
  "ring-slate-400/60 text-slate-400",
  "ring-orange-500/60 text-orange-500",
];

export default function Leaderboard() {
  const en =
    typeof document !== "undefined" &&
    document.documentElement.lang === "en";
  return (
    <Card className="w-full max-w-md">
      <CardContent className="p-5">
        <div className="mb-4 flex items-center justify-between">
          <h3 className="text-base font-semibold tracking-tight">
            {en ? "Leaderboard" : "リーダーボード"}
          </h3>
          <span className="text-xs text-muted-foreground">
            {en ? "This week" : "今週"}
          </span>
        </div>

        <ol className="space-y-1.5">
          {ENTRIES.map((e, i) => {
            const rank = i + 1;
            const isTop = rank <= 3;
            return (
              <li
                key={e.name}
                className={cn(
                  "flex items-center gap-3 rounded-lg px-3 py-2.5 transition-colors",
                  isTop ? "bg-muted/50" : "hover:bg-muted/30"
                )}
              >
                <span
                  className={cn(
                    "w-5 text-center text-sm font-bold tabular-nums",
                    isTop ? "text-foreground" : "text-muted-foreground"
                  )}
                >
                  {rank}
                </span>

                <div className="relative">
                  <div
                    className={cn(
                      "flex size-9 items-center justify-center rounded-full bg-primary/10 text-xs font-semibold text-primary",
                      isTop && "ring-2",
                      isTop && TOP_RING[i]
                    )}
                  >
                    {initials(e.name)}
                  </div>
                  {rank === 1 && (
                    <Crown className="absolute -right-1 -top-1.5 size-3.5 rotate-12 fill-amber-400 text-amber-500" />
                  )}
                </div>

                <span className="min-w-0 flex-1 truncate text-sm font-medium">
                  {e.name}
                </span>

                <span className="tabular-nums text-sm font-semibold">
                  {e.score.toLocaleString(en ? "en-US" : "ja-JP")}
                </span>

                <span
                  className={cn(
                    "flex w-10 items-center justify-end gap-0.5 text-xs font-medium tabular-nums",
                    e.move > 0 && "text-emerald-500",
                    e.move < 0 && "text-rose-500",
                    e.move === 0 && "text-muted-foreground"
                  )}
                >
                  {e.move > 0 && <TrendingUp className="size-3" />}
                  {e.move < 0 && <TrendingDown className="size-3" />}
                  {e.move === 0 && <Minus className="size-3" />}
                  {e.move !== 0 && Math.abs(e.move)}
                </span>
              </li>
            );
          })}
        </ol>
      </CardContent>
    </Card>
  );
}

