function makeBars(_seed: number, badAt: number[] = []): Status[] {
  return Array.from({ length: 40 }, (_, i) =>
    badAt.includes(i) ? (i % 7 === 0 ? "outage" : "degraded") : "operational"
  ).reverse();
}

