              }}
            />
          ))}

          {/* クラウンの間を埋める三角ファセット（半オフセットの放射で多面感を強める） */}
          {FACETS.map(({ i, angle, crownBright }) => (
            <div
              key={`crown-x-${i}`}
              className="absolute origin-top"
              style={{
                width: FACET_W,
                height: CROWN_H * 0.92,
