                transform: `rotateY(${angle + 360 / N / 2}deg) translateZ(${
                  R * 0.6
                }px) rotateX(40deg)`,
                background: crownGradient(0.4 + (1 - crownBright) * 0.5),
                clipPath: "polygon(50% 0%, 100% 100%, 0% 100%)",
                opacity: 0.85,
                backfaceVisibility: "visible",
              }}
            />
          ))}

